(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin((x+w1x)*0.04+t*0.5)*5 + Math.cos((y+w1y)*0.03-t*0.4)*4;
  const w2y = Math.cos((y+w1y)*0.035-t*0.45)*5 + Math.sin((x+w1x)*0.025+t*0.55)*4;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.5],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.0],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 2.0],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 2.5],
    [80+Math.sin(t*0.7+3)*70, 40+Math.cos(t*0.45+4)*50, 0.11, 2.1, 3.0],
    [400+Math.cos(t*0.55+2)*60, 220+Math.sin(t*0.65+1)*40, 0.05, 1.8, 3.5],
    [200+Math.sin(t*0.25)*110, 150+Math.cos(t*0.75+2)*70, 0.09, 2.4, 4.0],
    [300+Math.cos(t*0.4+3)*90, 100+Math.sin(t*0.5+5)*60, 0.07, 2.0, 4.5]
  ];
  let aS = 0, iS = 0, hS = 0;
  for (const [sX, sY, f, sp, ph] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp + ph);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5 + ph*0.5);
    hS += Math.cos(d*f*0.5 - t*sp*0.8 + ph*0.3);
  }
  const act = aS/10, inh = iS/10, harm = hS/10;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1) + Math.sin(sx*0.08+sy*0.06-t*0.6)*0.5)/2.5
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.06+t*0.3)*Math.sin(sy*0.07-t*0.4)*0.3;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const sp2 = (Math.sin(dist*0.08+ang*2-t*2.0) + Math.cos(dist*0.06-ang*5-t*0.8))*0.25;
  const sp3 = Math.sin(dist*0.03-ang*6+t*0.6)*0.2;
  const feed = act*0.5 + bg*0.3 + (sp1+sp2+sp3)*0.2;
  const kill = inh*0.6 + harm*0.2;
  const reaction = Math.tanh((feed - kill)*2.2);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)
    + Math.sin((sx+sy)*0.1+t)*0.5
    + Math.sin(sx*0.22-t*0.8)*Math.cos(sy*0.18+t*0.6)*0.3
    + Math.sin((sx-sy)*0.13+t*1.2)*0.2)*1.5)*0.3;
  const micro = Math.sin(sx*0.3+sy*0.2-t*3)*Math.sin(sx*0.25-sy*0.35+t*2.5)*0.15;
  const blend = reaction*0.6 + cell*0.25 + micro*0.15;
  const v = blend*0.5+0.5;
  const pal = [
    [5,10,45],[12,45,85],[18,90,120],[25,140,135],[60,175,130],
    [160,195,80],[220,190,60],[235,145,55],[210,95,65],[170,60,75],
    [110,35,75],[55,20,65],[20,15,55],[5,10,45]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.75 + Math.sin(reaction*Math.PI)*0.25;
  const edge = Math.abs(reaction) > 0.75 ? 1.2 : Math.abs(reaction) > 0.5 ? 1.05 : 0.95;
  const glow = Math.max(0, reaction - 0.3) * 0.3;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge + glow*60)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge + glow*30)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge + glow*10)|0)
  ];
}
